source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json, os, glob

base_cf = '/root/autodl-tmp/exp001/eval_results_cross_family'
base_14b = '/root/autodl-tmp/exp001/eval_results_14b'
base_7b = '/root/autodl-tmp/exp001/eval_results'

# Collect all accuracy data
families = {}

# Phi-4
for d in sorted(os.listdir(base_cf)):
    if d.startswith('phi-4_d'):
        path = os.path.join(base_cf, d, 'eval_results.json')
        if os.path.exists(path):
            data = json.load(open(path))
            for bench, bdata in data['benchmarks'].items():
                families.setdefault('phi4', {}).setdefault(bench, {})[d] = bdata['accuracy']

# Gemma-2
for d in sorted(os.listdir(base_cf)):
    if d.startswith('gemma'):
        path = os.path.join(base_cf, d, 'eval_results.json')
        if os.path.exists(path):
            data = json.load(open(path))
            for bench, bdata in data['benchmarks'].items():
                families.setdefault('gemma2', {}).setdefault(bench, {})[d] = bdata['accuracy']

# OLMo-2
for d in sorted(os.listdir(base_cf)):
    if d.startswith('olmo') and not d.endswith('.log'):
        path = os.path.join(base_cf, d, 'eval_results.json')
        if os.path.exists(path):
            data = json.load(open(path))
            for bench, bdata in data['benchmarks'].items():
                families.setdefault('olmo2', {}).setdefault(bench, {})[d] = bdata['accuracy']

# Qwen-14B
for d in sorted(os.listdir(base_14b)):
    if d.startswith('Qwen2.5-14B_d'):
        path = os.path.join(base_14b, d, 'eval_results.json')
        if os.path.exists(path):
            data = json.load(open(path))
            for bench, bdata in data['benchmarks'].items():
                families.setdefault('qwen14b', {}).setdefault(bench, {})[d] = bdata['accuracy']

# Qwen-7B (aligned)
for d in sorted(os.listdir(base_7b)):
    if d.startswith('Qwen2.5-7B_d') and d.endswith('_s42_aligned'):
        path = os.path.join(base_7b, d, 'eval_results.json')
        if os.path.exists(path):
            data = json.load(open(path))
            for bench, bdata in data['benchmarks'].items():
                families.setdefault('qwen7b', {}).setdefault(bench, {})[d] = bdata['accuracy']

print(json.dumps(families, indent=2))
